import{_ as l,a0 as p,w as u,s as a,ao as r,I as t,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"2017 年成為 Linux 專家的 4 個熱門技能 | LCTT x X-CMD","titleTemplate":false,"description":"2017 年成為 Linux 專家的 4 個熱門技能 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2017 年成為 Linux 專家的 4 個熱門技能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2017 年成為 Linux 專家的 4 個熱門技能 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20170103 4 hot skills for Linux pros in 2017","title":"2017 年成為 Linux 專家的 4 個熱門技能","tag":"201701","desc":""},"relativePath":"201701/20170103 4 hot skills for Linux pros in 2017.md","filePath":"[post].md"}'),d={name:"201701/20170103 4 hot skills for Linux pros in 2017.md"};function f(m,o,x,T,L,g){const s=p("Link");return u(),a("div",null,[o[21]||(o[21]=r('<h1 id="_2017-年成為-linux-專家的-4-個熱門技能" tabindex="-1">2017 年成為 Linux 專家的 4 個熱門技能 <a class="header-anchor" href="#_2017-年成為-linux-專家的-4-個熱門技能" aria-label="Permalink to “2017 年成為 Linux 專家的 4 個熱門技能”">​</a></h1><h3 id="你在新的一年裏需要刷哪些技能" tabindex="-1">你在新的一年裏需要刷哪些技能？ <a class="header-anchor" href="#你在新的一年裏需要刷哪些技能" aria-label="Permalink to “你在新的一年裏需要刷哪些技能？”">​</a></h3><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/lightbulb-idea-think-yearbook-lead.png?itok=56ovNk8n" alt="4 hot skills for Linux pros in 2017" title="4 hot skills for Linux pros in 2017"></p>',3)),t("p",null,[o[1]||(o[1]=e("圖片提供：",-1)),i(s,{href:"https://www.flickr.com/photos/internetarchivebookimages/14758810172/in/photolist-oubL5m-ocu2ck-odJwF4-oeq1na-odgZbe-odcugD-w7KHtd-owgcWd-oucGPe-oud585-rgBDNf-obLoQH-oePNvs-osVgEq-othPLM-obHcKo-wQR3KN-oumGqG-odnCyR-owgLg3-x2Zeyq-hMMxbq-oeRzu1-oeY49i-odumMM-xH4oJo-odrT31-oduJr8-odX8B3-obKG8S-of1hTN-ovhHWY-ow7Scj-ovfm7B-ouu1Hj-ods7Sg-qwgw5G-oeYz5D-oeXqFZ-orx8d5-hKPN4Q-ouNKch-our8E1-odvGSH-oweGTn-ouJNQQ-ormX8L-od9XZ1-roZJPJ-ot7Wf4"},{default:n(()=>[...o[0]||(o[0]=[e("Internet Archive Book Images",-1)])]),_:1}),o[2]||(o[2]=e("。由 Opensource.com 修改。 CC BY-SA 4.0",-1))]),o[22]||(o[22]=t("p",null,[e("成為 Linux 專家的一個問題是“專家”的定義在不斷變化。當我進入 Linux 世界的時候，那時認為成為一個 "),t("em",null,"Linux 專家"),e("，你需要能夠編譯自己的內核。天啊，如果你想在筆記本電腦上使用 Linux，即便你只是_用户_，你也必須編譯一個自定義內核。 如今編譯自己的內核通常是浪費時間。這不是説它並不重要，但在開源世界，我們建立在他人成功的基礎之上，而 Linux 發行版為我們提供了運行良好的內核。雖然“專家”的定義並不總是那麼劇烈變化，但對 IT 專業人員的需求每年都在變化。")],-1)),o[23]||(o[23]=t("p",null,"下面是 2017 年 Linux 專業人員的四個重要技能：",-1)),o[24]||(o[24]=t("h3",{id:"_1、-安全",tabindex:"-1"},[e("1、 安全 "),t("a",{class:"header-anchor",href:"#_1、-安全","aria-label":"Permalink to “1、 安全”"},"​")],-1)),t("p",null,[o[4]||(o[4]=e("我不是在討論安全專家或安全顧問。這些職位和服務當然很重要，但是隨着聯網設備滲透到我們生活的每一個方面，我們需要在我們做出的每一個決定中都具有",-1)),i(s,{href:"https://opensource.com/tags/security"},{default:n(()=>[...o[3]||(o[3]=[e("安全",-1)])]),_:1}),o[5]||(o[5]=e("意識。今年，我的妻子和我買了一台洗衣機和一台冰箱，它們都配備了藍牙。黑客攻入我的漂洗系統的想法可能看起來很傻，但這都是潛在的攻擊點。",-1))]),o[25]||(o[25]=t("p",null,"當激活工作、家庭或我們的口袋中的任何系統時，我們應該考慮它們可能引發的安全問題。而且因為像聯網烤麪包機這樣的物品不太可能及時獲得固件升級，我們需要按照普通設備可能遭到破壞的思路來設計其餘的系統。相比以前任何時候，我們更需要考慮來自防火牆內的攻擊。不要讓你的文件服務器被你的攪拌器破壞！",-1)),o[26]||(o[26]=t("h3",{id:"_2、-devops",tabindex:"-1"},[e("2、 DevOps "),t("a",{class:"header-anchor",href:"#_2、-devops","aria-label":"Permalink to “2、 DevOps”"},"​")],-1)),t("p",null,[i(s,{href:"https://opensource.com/tags/devops"},{default:n(()=>[...o[6]||(o[6]=[e("DevOps",-1)])]),_:1}),o[7]||(o[7]=e(" 不再是一個新概念。在過去兩三年裏，我們一直鼓勵員工學習 DevOps，以便他們能夠在工作中取得成功。這是個好建議，但這並不意味着我們應該完全依賴自動化工具來完成我們的工作。Chef、Puppet、Ansible、Salt Stack 及類似的工具是美好的，但我們需要了解背後發生了什麼，所以當發生一些不可避免的錯誤，我們應該知道如何解決它。",-1))]),o[27]||(o[27]=r('<p>使用 DevOps 的編程方法來計算，我們仍然需要能夠維護、修復和理解在代碼層之下運行的系統的人。沒有 Linux 專家，雲計算將是一個可怕的地方，即使那個雲在你自己的機房裏。</p><h3 id="_3、-開發" tabindex="-1">3、 開發 <a class="header-anchor" href="#_3、-開發" aria-label="Permalink to “3、 開發”">​</a></h3><p>作為系統管理員，20 年來，我從來沒有時間學習編程。這聽起來可能是一個藉口，但這是事實。我所有的開發技能就是基本的腳本編寫，以幫助我更快工作。不過，那些日子已經結束了。雖然我們需要在 DevOps 世界中擁有系統管理技能，但我們還需要系統管理員擁有編程技能。</p><p>如果你是一個像我一樣的老練的系統管理員，你可能已經採用 DevOps 並每天使用它。如果你真的想要勝過他人，你需要學習如何以編程方式解決問題，並且不要認為 Chef 或 Puppet 代碼只是配置文件。 每個 IT 專業人員都至少需要掌握編程的概念，因為 DevOps 代碼至少在某種程度上抽象了 IT 的每個方面。</p><h3 id="_4、-軟技能" tabindex="-1">4、 軟技能 <a class="header-anchor" href="#_4、-軟技能" aria-label="Permalink to “4、 軟技能”">​</a></h3><p>通常，我們在準備職業生涯時所考慮的最後一件事是所謂的 <em>軟技能</em> - 社交和溝通技巧 - 但是它們可能是最有可能決定你走向成功的技能。無論你正在尋找一份新工作，還是試圖適應當前職業生涯的變化，軟技能是至關重要的。</p><p>劃分 IT 各個領域的標準是交錯的，並且良好的溝通能力使得這些模糊的分野成為一個有利條件，而不是絆腳石。我們正生活在一個開發人員圍繞着服務器，而運維團隊編寫 Ruby 代碼來維護服務器農場的世界裏。這些都是 IT 中的大膽的新思想，如果人們不能在不同部門間很好的溝通，工作場所將迅速有敵對氣氛。此外，IT 人員總是需要與其他業務領域的人員進行有效溝通。而且，現在比以往有更大的需求。</p><p>你計劃在 2017 年裏添加什麼到你的技能中？在評論欄中讓我們知道吧。</p><hr><p>作者簡介：</p><p><img src="https://opensource.com/sites/default/files/styles/profile_pictures/public/Shawn%20Powers%20350%20x%20250%20px_2.jpg?itok=6n0E_-Z2" alt=""></p><p>Shawn Powers - 自 2009 年起是 CBT Nuggets (www.cbtnuggets.com) 的一名 IT 訓練員，專於 Linux、Chef 及為大規模網絡集成多個平台。他在 2016 年 12 月發佈了一個在線高級 Linux 認證課程（LPIC-2）。</p><hr>',13)),t("p",null,[o[9]||(o[9]=e("via: ",-1)),i(s,{href:"https://opensource.com/article/17/1/yearbook-4-hot-skills-linux-pros-2017"},{default:n(()=>[...o[8]||(o[8]=[e("https://opensource.com/article/17/1/yearbook-4-hot-skills-linux-pros-2017",-1)])]),_:1})]),t("p",null,[o[13]||(o[13]=e("作者：",-1)),i(s,{href:"https://opensource.com/users/shawnpowers"},{default:n(()=>[...o[10]||(o[10]=[e("Shawn Powers",-1)])]),_:1}),o[14]||(o[14]=e(" 譯者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:n(()=>[...o[11]||(o[11]=[e("geekpi",-1)])]),_:1}),o[15]||(o[15]=e(" 校對：",-1)),i(s,{href:"https://github.com/jasminepeng"},{default:n(()=>[...o[12]||(o[12]=[e("jasminepeng",-1)])]),_:1})]),t("p",null,[o[18]||(o[18]=e("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[16]||(o[16]=[e("LCTT",-1)])]),_:1}),o[19]||(o[19]=e(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:n(()=>[...o[17]||(o[17]=[e("Linux中國",-1)])]),_:1}),o[20]||(o[20]=e(" 榮譽推出",-1))])])}const C=l(d,[["render",f]]);e